{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Glafenine, which shares the 7-chloro-4-aminoquinoline core, had an absolute oral bioavailability of about 33% in healthy volunteers, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Piperaquine, a bis-7-chloroquinoline antimalarial, showed a modeled oral bioavailability of 0.77 in humans, supporting high bioavailability for the related quinoline core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Clomipramine, a lipophilic tertiary-amine tricyclic with a chlorinated ring, had an absolute oral bioavailability of about 48% in healthy volunteers, supporting high F for the query's basic amine and chloroaromatic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Chlorpheniramine, containing a dimethylamino group and a chlorophenyl ring, has reported oral bioavailability values of 25-50% in humans, all above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Zotepine, a tricyclic with a dimethylaminoethoxy side chain and chlorinated ring, had absolute bioavailability of only 7-13%, providing contradictory low-F evidence, but its lower structural transfer to the quinoline query limits its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pyronaridine, a larger polybasic antimalarial, was reported to have low human bioavailability, a contradictory signal; however, the query is smaller and lacks the extensive polar/basic substitution that likely limits pyronaridine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 7-chloro-4-aminoquinoline with a basic benzylamine side chain. Direct quinoline analogues (glafenine F ~33%, piperaquine F ~77%) and several basic lipophilic drugs (clomipramine ~48%, chlorpheniramine 25-50%) support F >= 20%. The low-F examples are less structurally transferable or limited, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "Human absolute F data for close 4-aminoquinoline analogues are limited, and the mechanism of pyronaridine's low bioavailability is not well characterized.",
    "No data are available on first-pass metabolism, intestinal permeability, or transporter effects specific to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

